// Index Scraped Emails — n8n Code node (Run Once for All Items).
//
// Builds a domain -> email map from the committed ICH GCP CSV, so the Apollo
// stage can answer "do we already have an address for this lead?" without a
// per-lead fetch and without a credit.
//
// Why this node exists at all: the scrape captured a `Web:`-adjacent `E-mail:`
// field on every ichgcp company profile, but `leads` has no email column
// (Section 8, locked), so ingestion dropped it on the floor. The address was
// never lost -- it is still in data/ichgcp_leads.csv, which the ingestion
// workflow already publishes to raw.githubusercontent.com. 92 of the 123 rows
// carry one. Reading it back here is free; asking Apollo for it is not.
//
// The map is built once per batch rather than per lead: one fetch, one parse,
// then an O(1) lookup per lead in Resolve Contact.

const rows = $input.all();

// Matches the scraper's own normalisation (scrape_ichgcp.py) and the ingestion
// upsert, which writes leads.domain verbatim from this same column. Lowercase +
// trim + strip a leading www. is defensive, not corrective: an exact match is
// the contract, and a mismatch would silently cost a credit rather than fail.
function normDomain(d) {
  if (typeof d !== 'string') return '';
  return d.trim().toLowerCase().replace(/^www\./, '').replace(/[./]+$/, '');
}

// Deliberately permissive. The goal is to reject junk that would be written
// into contacts.email as if it were reachable -- not to adjudicate deliverability,
// which is the sending workflow's job and the mailbox's after that.
function looksLikeEmail(e) {
  if (typeof e !== 'string') return false;
  const s = e.trim();
  if (!s || s.length > 254) return false;
  if (/\s/.test(s)) return false;
  const at = s.indexOf('@');
  if (at < 1 || at !== s.lastIndexOf('@')) return false;
  const host = s.slice(at + 1);
  return host.indexOf('.') > 0 && !host.startsWith('.') && !host.endsWith('.');
}

const byDomain = {};
let withEmail = 0;
let malformed = 0;

for (const r of rows) {
  const j = r.json || {};
  const domain = normDomain(j.domain);
  if (!domain) continue;
  const raw = typeof j.email === 'string' ? j.email.trim() : '';
  if (!raw) continue;
  if (!looksLikeEmail(raw)) {
    malformed++;
    continue;
  }
  // First row wins. A domain appearing on several country pages carries the
  // same profile-page email each time; this only decides ties, it does not
  // merge anything.
  if (!byDomain[domain]) {
    byDomain[domain] = raw;
    withEmail++;
  }
}

return [
  {
    json: {
      by_domain: byDomain,
      csv_rows: rows.length,
      domains_with_email: withEmail,
      malformed_emails: malformed,
    },
  },
];

// Harvest Site Emails -- n8n Code node (Run Once for All Items).
//
// The third free contact source, added 2026-10-07: an e-mail address the
// company has published on its own website.
//
// Why this exists. Of the nine qualifying leads stuck with no channel on
// 2026-10-07, five publish an address on their own site -- ivrs.org.in
// (info@), rotrial.com (contact_us@), ee-cro.com (office@ plus two named
// mailboxes), delphiniumcro.com (info@, client@) and hvivo.com (bd@). Nothing
// had to be bought and nothing had to be guessed; the pages were simply never
// read for an address. Same shape as the finding that started this stage --
// every ichgcp profile carried an e-mail and ingestion dropped it.
//
// Why the fetch happens HERE and not in enrichment. Workflow 2 already fetches
// these very pages, but it keeps none of their text: the LinkedIn profiles are
// harvested from the blob by regex and the rest goes to the model and is
// discarded. Adding the harvest there would only help leads enriched from then
// on -- the 274 already in the table would each need a re-enrichment (a GPU
// call) and a re-score (a rationale call and a ClinicalTrials.gov lookup) to
// get at something that costs neither. So the stage that needs an address goes
// and looks for one, which also means it reads the site as it is today rather
// than as it was when the lead was enriched.
//
// WHAT IS AND IS NOT TAKEN -- the rule the whole node turns on:
//
//   * only an address that is literally on the page, as a mailto: link or as
//     text. Nothing is pattern-derived: no first.last@, no info@<domain> on the
//     grounds that most companies have one. A guessed address is a different
//     kind of thing from a published one, and `contacts.verified` draws exactly
//     that line (Section 9 / README).
//   * only the lead's own domain, or a subdomain of it. This is not fussiness:
//     mtz-clinical.pl publishes only @pratia.com addresses (it was acquired),
//     cebisinternational.com only @cebis-int.com, and archerresearch.eu only
//     Wix's @sentry.wixpress.com telemetry. All three are the wrong company or
//     no company, and all three are rejected by this one rule.
//   * never a mailbox that is not for business contact -- careers@, ir@,
//     privacy@, noreply@ and the rest of NEVER below. hvivo.com publishes
//     bd@, careers@ and ir@; only one of those is a person to write to.
//
// An address found here is written `verified = true`: it is a first-party
// address the company published about itself, which is the same ground the
// ichgcp profile address stands on (README, "What `verified` means").
//
// Master Ref build rule 3: all of this is string matching. No model call.

const helpers = this.helpers;

const cfg = $('Config').first().json;
const index = $('Index Scraped Emails').first().json;
const byDomain = (index && index.by_domain) || {};

// One homepage plus at most this many contact-ish subpages, per lead. The
// batch is bounded (Config.batch_size, 10), so a run is at most ~50 requests
// spread over as many different hosts -- each one the lead's own site.
const MAX_PAGES = Number(cfg.site_max_pages) || 5;
const TIMEOUT_MS = 12000;
const RETRY_TIMEOUT_MS = 20000;
const CONCURRENCY = 3;
const UA = 'NovaScoutBot/1.0 (+https://github.com/abdullahamir2308/nova-scout)';

// Where a published address actually lives. Contact and imprint pages first --
// Germany, Austria and Switzerland put a legally required address on
// /impressum, which is the single most reliable page on a European CRO's site.
const PAGE_KEYWORDS = [
  'contact', 'contacts', 'contact-us', 'contactus', 'get-in-touch', 'reach-us', 'enquiry', 'enquiries',
  'impressum', 'imprint', 'legal-notice', 'kontakt', 'kontakty', 'contatti', 'contacto', 'contato',
  'iletisim', 'kapcsolat', 'contactati', 'contacte', 'nous-contacter', 'kontaktai', 'kontakta-oss',
  'about', 'about-us', 'aboutus', 'team', 'our-team', 'people', 'leadership', 'management',
];
const FALLBACK_PATHS = ['/contact', '/contact-us', '/kontakt', '/impressum', '/about'];

// Local parts that are never a business-contact mailbox. A cold email to
// careers@ or privacy@ is worse than no email at all -- it reaches the wrong
// desk and reads as a mass send, which is what Section 5's whole warm-up is
// built to avoid. noreply/postmaster-class addresses are not even read.
const NEVER = [
  'careers', 'career', 'jobs', 'job', 'recruitment', 'recruiting', 'recruit', 'hr', 'cv', 'cvs',
  'apply', 'applications', 'internship', 'volunteer',
  'ir', 'investor', 'investors', 'investorrelations', 'shareholders',
  'press', 'media', 'pr', 'newsroom', 'communications',
  'privacy', 'dpo', 'gdpr', 'kvkk', 'legal', 'compliance', 'ethics', 'whistleblower',
  'abuse', 'postmaster', 'hostmaster', 'webmaster', 'noreply', 'donotreply',
  'bounce', 'bounces', 'unsubscribe', 'notifications', 'notification',
  'billing', 'invoice', 'invoices', 'accounts', 'accounting', 'finance', 'payment', 'payments',
  'newsletter', 'subscribe', 'marketing',
  'test', 'example', 'sample', 'demo', 'sentry', 'wordpress', 'root',
];

// Preference, best first. Not a filter -- anything not in NEVER is usable; this
// only decides which of several published addresses to write. Section 12 names
// the buyer ("founder, Managing Director, or BD Director"), so a business
// development mailbox outranks a general one, and a general one outranks an
// operational inbox like support@ or client@ answered by a different team.
const PREFER = [
  ['bd', 'businessdevelopment', 'business', 'bizdev', 'sales', 'commercial',
    'partnership', 'partnerships', 'partner'],
  ['info', 'contact', 'contactus', 'hello', 'enquiry', 'enquiries', 'inquiry', 'inquiries',
    'office', 'mail', 'email', 'general', 'reception', 'welcome', 'connect', 'kontakt', 'iletisim'],
];

// A role inbox is a company address, not a person's. Flagged, never rejected --
// the same list and the same reason as code_resolve.js: the distinction has to
// survive into the report and the review queue, because the founder's name must
// never be presented as the owner of one (build rule 6).
const ROLE_LOCALPARTS = [
  'info', 'contact', 'hello', 'connect', 'office', 'admin', 'enquiry',
  'enquiries', 'inquiry', 'inquiries', 'mail', 'sales', 'support', 'general',
];

// Deliberately narrow: no spaces, no angle brackets, a dotted host, a 2+ letter
// TLD. An obfuscated address ("info [at] example.com") is NOT matched, because
// un-obfuscating one is a guess about what the page meant.
const EMAIL_RE = /[A-Za-z0-9!#$%&'*+/=?^_`{|}~.-]+@[A-Za-z0-9](?:[A-Za-z0-9-]*[A-Za-z0-9])?(?:\.[A-Za-z0-9](?:[A-Za-z0-9-]*[A-Za-z0-9])?)+/g;
const MAILTO_RE = /mailto:([^"'>\s?&]+)/gi;

// `name@2x.png` and friends are how a sprite file looks to an e-mail regex.
const ASSET_TLDS = ['png', 'jpg', 'jpeg', 'gif', 'svg', 'webp', 'ico', 'bmp', 'css', 'js',
  'json', 'woff', 'woff2', 'ttf', 'eot', 'pdf', 'webmanifest', 'map'];

function str(v) {
  return v === null || v === undefined ? '' : String(v).trim();
}

function normDomain(d) {
  return str(d).toLowerCase().replace(/^https?:\/\//, '').replace(/^www\./, '')
    .replace(/[/].*$/, '').replace(/[:.]+$/, '');
}

// ---------------------------------------------------------------------------
// HTTP -- the n8n Code sandbox has no fetch, so this is the node's own helper,
// the same shape Workflow 2's code_fetch.js uses, TLS fallback rung included.
// Reading public marketing pages sends no credentials, so a broken certificate
// is a data-quality signal, not a confidentiality risk.
// ---------------------------------------------------------------------------

async function get(url, opts) {
  const o = opts || {};
  return await helpers.httpRequest({
    method: 'GET',
    url: url,
    timeout: o.timeout || TIMEOUT_MS,
    headers: { 'User-Agent': UA, Accept: 'text/html,application/xhtml+xml', 'Accept-Language': 'en,*;q=0.5' },
    json: false,
    returnFullResponse: true,
    ignoreHttpStatusErrors: true,
    skipSslCertificateValidation: o.insecure === true,
  });
}

function homepageLadder(domain) {
  const bare = domain.replace(/^www\./, '');
  const rungs = [{ label: 'https', url: 'https://' + domain + '/', timeout: TIMEOUT_MS, insecure: false }];
  if (domain === bare) {
    rungs.push({ label: 'https+www', url: 'https://www.' + bare + '/', timeout: RETRY_TIMEOUT_MS, insecure: false });
  }
  rungs.push({ label: 'https+insecure', url: 'https://' + domain + '/', timeout: RETRY_TIMEOUT_MS, insecure: true });
  rungs.push({ label: 'http', url: 'http://' + domain + '/', timeout: RETRY_TIMEOUT_MS, insecure: false });
  return rungs;
}

// The WHATWG URL constructor is not in the sandbox (verified during Workflow 2:
// using it fails inside a try/catch and turns link discovery into a silent
// no-op). Absolute and root-relative hrefs only -- enough for a nav link.
function sameHostLink(href, origin, host) {
  let h = str(href);
  if (!h || h.charAt(0) === '#') return null;
  if (/^(mailto:|tel:|javascript:|data:|sms:|whatsapp:)/i.test(h)) return null;
  h = h.split('#')[0].split('?')[0];
  if (!h) return null;
  if (/^https?:\/\//i.test(h)) {
    const m = h.match(/^(https?):\/\/([^/?#]+)([^?#]*)/i);
    if (!m) return null;
    if (m[2].toLowerCase().replace(/^www\./, '').replace(/:\d+$/, '') !== host) return null;
    return m[1].toLowerCase() + '://' + m[2].toLowerCase() + (m[3] || '/');
  }
  if (h.slice(0, 2) === '//') return null;
  if (h.charAt(0) !== '/') return null;
  return origin + h;
}

function discover(html, origin, host) {
  const out = [];
  const seen = {};
  const re = /<a\b[^>]*?href\s*=\s*["']([^"']+)["']/gi;
  let m;
  while ((m = re.exec(html)) !== null) {
    const abs = sameHostLink(m[1], origin, host);
    if (!abs) continue;
    const clean = abs.replace(/\/+$/, '');
    if (!clean || seen[clean]) continue;
    const slug = clean.toLowerCase();
    for (let i = 0; i < PAGE_KEYWORDS.length; i++) {
      if (slug.indexOf(PAGE_KEYWORDS[i]) !== -1) {
        seen[clean] = true;
        // The keyword's own rank orders the pages: a /contact page before an
        // /about page before a /team page.
        out.push({ url: clean, rank: i });
        break;
      }
    }
  }
  out.sort(function (a, b) { return a.rank - b.rank; });
  return out.map(function (x) { return x.url; });
}

// ---------------------------------------------------------------------------
// Harvesting
// ---------------------------------------------------------------------------

function onOwnDomain(address, domain) {
  const at = address.lastIndexOf('@');
  if (at <= 0 || !domain) return false;
  const host = address.slice(at + 1).toLowerCase().replace(/\.+$/, '');
  if (host === domain) return true;
  return host.length > domain.length + 1 &&
    host.slice(host.length - domain.length - 1) === '.' + domain;
}

function looksLikeAsset(address) {
  const tld = address.slice(address.lastIndexOf('.') + 1).toLowerCase();
  return ASSET_TLDS.indexOf(tld) !== -1;
}

function localPart(address) {
  return address.slice(0, address.lastIndexOf('@')).toLowerCase();
}

function isNever(address) {
  const lp = localPart(address);
  // Whole-localpart match, plus the common "careers.uk@" / "no-reply-2@"
  // shapes. Never a substring test: under one, "contact@" would match "act".
  if (NEVER.indexOf(lp) !== -1) return true;
  if (/^no[._-]?reply/.test(lp) || /^do[._-]?not[._-]?reply/.test(lp)) return true;
  const parts = lp.split(/[._+-]/).filter(Boolean);
  return parts.length > 1 && NEVER.indexOf(parts[0]) !== -1;
}

function preferenceTier(address) {
  const lp = localPart(address);
  for (let i = 0; i < PREFER.length; i++) {
    if (PREFER[i].indexOf(lp) !== -1) return i;
  }
  return PREFER.length;
}

// Two independent sources agreeing on the person beats any title string --
// the rule code_pick_contact.js already applies to an Apollo candidate. A
// mailbox whose local part carries the founder's own name
// (ilse.eder@ee-cro.com for "Ilse Eder") is that agreement, and it is the only
// case where a name is written as the owner of an address.
function matchesFounder(address, founderName) {
  const name = str(founderName).toLowerCase();
  if (!name) return false;
  const words = name.replace(/[^a-z\s'-]/g, ' ').split(/\s+/)
    .filter(function (w) { return w.length >= 3; });
  if (words.length < 2) return false;
  const lp = localPart(address).replace(/[^a-z]/g, '');
  const first = words[0].replace(/[^a-z]/g, '');
  const last = words[words.length - 1].replace(/[^a-z]/g, '');
  if (!first || !last || first === last) return false;
  return lp.indexOf(first) !== -1 && lp.indexOf(last) !== -1;
}

// Every address literally present in `html`, on this lead's own domain.
// `found` is carried across pages, and a mailto: beats a later text sighting of
// the same address because it is unambiguously an address the page offers.
function harvest(html, domain, found) {
  let m;
  MAILTO_RE.lastIndex = 0;
  while ((m = MAILTO_RE.exec(html)) !== null) {
    let a;
    try {
      a = decodeURIComponent(m[1]).trim().toLowerCase();
    } catch (e) {
      a = m[1].trim().toLowerCase();
    }
    EMAIL_RE.lastIndex = 0;
    const whole = EMAIL_RE.exec(a);
    EMAIL_RE.lastIndex = 0;
    if (!whole || whole[0] !== a) continue;
    if (onOwnDomain(a, domain) && !looksLikeAsset(a)) found[a] = 'mailto';
  }
  EMAIL_RE.lastIndex = 0;
  while ((m = EMAIL_RE.exec(html)) !== null) {
    const a = m[0].toLowerCase().replace(/^\.+/, '').replace(/\.+$/, '');
    if (!onOwnDomain(a, domain) || looksLikeAsset(a)) continue;
    if (!found[a]) found[a] = 'text';
  }
  return found;
}

function pick(addresses, founderName) {
  const usable = addresses.filter(function (a) { return !isNever(a); });
  if (!usable.length) return null;
  usable.sort(function (a, b) {
    const fa = matchesFounder(a, founderName) ? 0 : 1;
    const fb = matchesFounder(b, founderName) ? 0 : 1;
    if (fa !== fb) return fa - fb;
    const ta = preferenceTier(a);
    const tb = preferenceTier(b);
    if (ta !== tb) return ta - tb;
    // Shortest, then alphabetical: deterministic, so two runs of the same
    // batch write the same address.
    if (a.length !== b.length) return a.length - b.length;
    return a < b ? -1 : 1;
  });
  return usable[0];
}

// ---------------------------------------------------------------------------
// Node body
// ---------------------------------------------------------------------------

async function processLead(item) {
  const lead = item.json;
  const out = Object.assign({}, lead, {
    site_email: null,
    site_email_how: null,
    site_email_role_inbox: false,
    site_email_is_founder: false,
    site_email_candidates: [],
    site_email_rejected: [],
    site_pages_fetched: 0,
    site_fetch_errors: [],
    site_lookup: 'skipped',
  });

  const domain = normDomain(lead.domain);
  if (!domain) return out;

  // A lead whose address was already in the committed CSV needs nothing from
  // its website: Resolve Contact prefers the scraped address anyway, so a fetch
  // here would be a request to a prospect's server for data we already hold.
  if (str(byDomain[domain])) {
    out.site_lookup = 'not-needed';
    return out;
  }

  out.site_lookup = 'no-address-found';

  let home = null;
  let origin = null;
  let insecure = false;
  const rungs = homepageLadder(domain);
  for (let i = 0; i < rungs.length; i++) {
    const rung = rungs[i];
    try {
      const r = await get(rung.url, { timeout: rung.timeout, insecure: rung.insecure });
      if (r.statusCode >= 400) {
        out.site_fetch_errors.push(rung.label + ' / -> HTTP ' + r.statusCode);
        continue;
      }
      home = r;
      origin = rung.url.replace(/\/$/, '');
      insecure = rung.insecure;
      break;
    } catch (e) {
      out.site_fetch_errors.push(rung.label + ' / -> ' + str(e.message || e).slice(0, 120));
    }
  }

  if (!home) {
    out.site_lookup = 'unreachable';
    return out;
  }

  const found = {};
  const homeHtml = str(home.body);
  out.site_pages_fetched = 1;
  harvest(homeHtml, domain, found);

  const host = domain.replace(/^www\./, '');
  // Links the site itself offers first; then the literal paths, so a site whose
  // nav hides its contact page is still covered. `guessed` marks the second
  // kind: a 404 on a path nobody linked is not a fault worth reporting, and
  // recording it would bury the real failures under four misses per lead.
  const targets = discover(homeHtml, origin, host).slice(0, MAX_PAGES - 1)
    .map(function (u) { return { url: u, guessed: false }; });
  for (let i = 0; i < FALLBACK_PATHS.length && targets.length < MAX_PAGES - 1; i++) {
    const u = origin + FALLBACK_PATHS[i];
    let have = false;
    for (let k = 0; k < targets.length; k++) {
      if (targets[k].url === u) have = true;
    }
    if (!have) targets.push({ url: u, guessed: true });
  }

  for (let i = 0; i < targets.length; i++) {
    const target = targets[i];
    try {
      const r = await get(target.url, { insecure: insecure });
      if (r.statusCode >= 400) {
        if (!(target.guessed && r.statusCode === 404)) {
          out.site_fetch_errors.push(target.url.replace(origin, '') + ' -> HTTP ' + r.statusCode);
        }
        continue;
      }
      out.site_pages_fetched++;
      harvest(str(r.body), domain, found);
    } catch (e) {
      out.site_fetch_errors.push(target.url.replace(origin, '') + ' -> ' + str(e.message || e).slice(0, 120));
    }
  }

  const all = Object.keys(found).sort();
  out.site_email_candidates = all;
  out.site_email_rejected = all.filter(function (a) { return isNever(a); });

  const chosen = pick(all, lead.founder_name);
  if (!chosen) return out;

  out.site_email = chosen;
  out.site_email_how = found[chosen];
  out.site_email_role_inbox = ROLE_LOCALPARTS.indexOf(localPart(chosen)) !== -1;
  out.site_email_is_founder = matchesFounder(chosen, lead.founder_name);
  out.site_lookup = 'found';
  return out;
}

const items = $input.all();
const results = new Array(items.length);
let next = 0;
const workers = [];
for (let w = 0; w < Math.min(CONCURRENCY, items.length); w++) {
  workers.push((async function () {
    for (;;) {
      const i = next++;
      if (i >= items.length) return;
      results[i] = await processLead(items[i]);
    }
  })());
}
await Promise.all(workers);

return results.map(function (r) { return { json: r }; });

// Resolve Contact — n8n Code node (Run Once for Each Item).
//
// Decides, per qualified lead, whether Apollo needs to be called at all.
//
// Section 7's ordering rule keeps Apollo on the free tier by spending only on
// leads that already cleared Section 9's score gate (Config.min_fit_score,
// parsed from the doc). This node applies the same principle one level further
// in: of those, spend only on the ones we do not already have a way to reach.
// Three free sources are checked first:
//
//   1. the ichgcp profile-page email, via the committed CSV index
//   2. an address the company publishes on its own website (Harvest Site
//      Emails, 2026-10-07) -- literally on the page, its own domain only
//   3. name/title/linkedin <- enrichments, harvested in Workflow 2
//
// A lead with an address from 1 or 2 skips the Apollo call entirely. So does a
// lead with no address but a founder LinkedIn profile the company's own site
// gave (2026-10-06): it is written as a LinkedIn-only contact -- no email, not
// verified -- so Workflow 4 drafts the DM Section 6 has a human send. Apollo's
// free plan cannot answer anyway (Section 9), and a profile that regex-matched
// the named founder (code_normalise.js) is a channel nobody had to buy.
//
// WHY 1 BEATS 2. The ichgcp address is in a file this repo committed, so it is
// the same address on every run for ever; the site is whatever it serves today.
// Nothing is lost by preferring the stable one -- both are first-party, both
// are `verified`, and where the site has a better address the CSV usually has
// none at all (that is why this source was added).
//
// Note what is NOT inferred here. A role inbox (info@, contact@) is a company
// address, not a person's, and pairing it with the founder's name would assert
// something no source states. Both facts are still carried -- Workflow 4 drafts
// an email variant and a LinkedIn variant separately, so the address and the
// person feed different channels -- but the row records only what a source
// actually said, per build rule 6. The one exception is a site mailbox whose
// local part carries the founder's own name (ilse.eder@ee-cro.com for "Ilse
// Eder"): there two independent sources agree on the person, which is the same
// corroboration code_pick_contact.js ranks an Apollo candidate by.

const lead = $input.item.json;
const index = $('Index Scraped Emails').first().json;
const byDomain = (index && index.by_domain) || {};

function normDomain(d) {
  if (typeof d !== 'string') return '';
  return d.trim().toLowerCase().replace(/^www\./, '').replace(/[./]+$/, '');
}

function clean(v) {
  if (typeof v !== 'string') return null;
  const s = v.trim();
  return s ? s : null;
}

const domain = normDomain(lead.domain);
const scrapedEmail = clean(byDomain[domain]);

// Harvest Site Emails ran immediately upstream and passed the lead's row
// through with these added. It only fetches a site when the CSV has no address
// for the domain, so `site_email` is null whenever `scrapedEmail` is set.
const siteEmail = clean(lead.site_email);

// A role inbox is still a real, published, first-party address -- it is how the
// company asked to be contacted. It is flagged rather than rejected so the
// distinction survives into the report and the review queue.
const ROLE_LOCALPARTS = [
  'info', 'contact', 'hello', 'connect', 'office', 'admin', 'enquiry',
  'enquiries', 'inquiry', 'inquiries', 'mail', 'sales', 'support', 'general',
];

function isRole(address) {
  if (!address) return false;
  return ROLE_LOCALPARTS.indexOf(address.split('@')[0].toLowerCase()) >= 0;
}

// Enrichment already found these on the company's own site in Workflow 2. They
// cost nothing to reuse and are the only person-level facts available before a
// credit is spent.
const founderName = clean(lead.founder_name);
const founderLinkedin = clean(lead.founder_linkedin);
const founderTitle = clean(lead.founder_title);

const base = {
  lead_id: lead.lead_id,
  domain: lead.domain,
  company_name: lead.company_name,
  country: lead.country,
  fit_score: lead.fit_score,
};

if (scrapedEmail) {
  const roleInbox = isRole(scrapedEmail);
  return {
    json: Object.assign({}, base, {
      needs_apollo: false,
      source: 'ichgcp_scrape',
      contact: {
        // Null unless the site itself named someone. A role inbox gets no name.
        name: founderName,
        title: founderTitle,
        email: scrapedEmail,
        linkedin_url: founderLinkedin,
        apollo_id: null,
        // A first-party address the company published about itself. Not a guess
        // and not an inference, so it is written verified. See README for how
        // this flag is defined across every source.
        verified: true,
      },
      evidence:
        'email from the company profile page on ichgcp.net (' +
        (roleInbox ? 'role inbox' : 'named mailbox') + '), captured at ingestion' +
        (founderName
          ? '; name/title/LinkedIn from the Workflow 2 site extraction'
          : '; no person named on the site'),
      role_inbox: roleInbox,
      credits_saved: 1,
    }),
  };
}

// No address in the CSV, but the company publishes one on its own site. Taken
// verbatim from the page -- a mailto: link or text on it -- and only on the
// lead's own domain (Harvest Site Emails has the rules and the evidence for
// each of them). Published, so `verified` is true for the same reason the
// ichgcp address is.
if (siteEmail) {
  const roleInbox = lead.site_email_role_inbox === true || isRole(siteEmail);
  const isFounderMailbox = lead.site_email_is_founder === true;
  const how = clean(lead.site_email_how) || 'text';
  const pages = Number(lead.site_pages_fetched) || 0;
  return {
    json: Object.assign({}, base, {
      needs_apollo: false,
      source: 'site_published',
      contact: {
        // The name goes on the row either way -- it is a real fact from the
        // site -- but only a mailbox carrying the founder's own name is a case
        // where any source says the person owns the address, and `evidence`
        // is where that difference is recorded.
        name: founderName,
        title: founderTitle,
        email: siteEmail,
        linkedin_url: founderLinkedin,
        apollo_id: null,
        verified: true,
      },
      evidence:
        'email published on the company\'s own website, found as ' + how +
        ' across ' + pages + ' page' + (pages === 1 ? '' : 's') + ' (' +
        (isFounderMailbox
          ? 'mailbox carries the founder\'s name, so two sources agree on the person'
          : roleInbox ? 'role inbox' : 'named mailbox') + ')' +
        (founderName && !isFounderMailbox
          ? '; name/title/LinkedIn from the Workflow 2 site extraction, not asserted to own this inbox'
          : ''),
      role_inbox: roleInbox,
      site_email_candidates: lead.site_email_candidates || [],
      credits_saved: 1,
    }),
  };
}

// No address anywhere, but the site named its founder and gave a LinkedIn
// profile for them. Only a personal profile counts (/in/...): enrichment can
// also see a company page, which is not a person to write to. Nothing is
// inferred -- the email stays null, so the row says exactly what the sources
// said, and it is not `verified` (that flag means a confirmed address; there is
// none).
const PROFILE_URL = /^https?:\/\/(?:[a-z0-9-]+\.)?linkedin\.com\/in\/[^\s/?#]+/i;
if (founderLinkedin && PROFILE_URL.test(founderLinkedin)) {
  return {
    json: Object.assign({}, base, {
      needs_apollo: false,
      source: 'enrichment_linkedin',
      contact: {
        name: founderName,
        title: founderTitle,
        email: null,
        linkedin_url: founderLinkedin,
        apollo_id: null,
        verified: false,
      },
      evidence:
        'no email on the ichgcp profile page and none published on the site' +
        (Number(lead.site_pages_fetched) ? ' (' + lead.site_pages_fetched + ' pages read)' : '') +
        '; LinkedIn profile' + (founderName ? ', name' : '') + (founderTitle ? ' and title' : '') +
        ' from the Workflow 2 site extraction -- written LinkedIn-only, Apollo not called',
      role_inbox: false,
      credits_saved: 1,
    }),
  };
}

// Nothing free to reach them with. This is the only path that reaches Apollo --
// which, on this account's Free plan, refuses (Section 9). What happens then is
// code_pick_contact.js's business: the lead is recorded in `contact_attempts`
// so it stops filling every batch, and it surfaces in `needs_manual_contact`.
// The two free lookups are summarised here so that record can say what was
// actually tried.
return {
  json: Object.assign({}, base, {
    needs_apollo: true,
    source: 'apollo',
    domain: domain,
    // Passed through so Pick Best Contact can prefer the person the site itself
    // named, when Apollo returns several plausible people.
    known_founder_name: founderName,
    known_founder_linkedin: founderLinkedin,
    known_founder_title: founderTitle,
    // What the free sources did, for the attempt record and the manual queue.
    free_sources: {
      scraped_email: false,
      site_lookup: clean(lead.site_lookup) || 'skipped',
      site_pages_fetched: Number(lead.site_pages_fetched) || 0,
      site_candidates: lead.site_email_candidates || [],
      site_rejected: lead.site_email_rejected || [],
      founder_linkedin: founderLinkedin ? 'not a personal profile' : 'none found',
    },
    credits_saved: 0,
  }),
};

// Pick Best Contact — n8n Code node (Run Once for Each Item).
//
// Ranks an Apollo people-search response and decides whether any result is
// worth spending an enrichment credit on.
//
// Section 12's ICP names the buyer: "CRO founder, Managing Director, or BD
// Director". This node encodes that as an ordered preference rather than a
// filter, so a company whose only senior person is titled something unexpected
// still surfaces -- but never outranks an actual founder.
//
// Three outcomes, and the difference between the last two is the whole point of
// the node:
//
//   retry     the call itself failed (rate limit, timeout, outage). Nothing is
//             written to `contacts`; the lead stays 'scored' and the next run
//             tries again. Recording "no match" here would be a lie about what
//             Apollo said.
//   no match  Apollo answered, and nothing at this domain clears the bar. A
//             tombstone row is written so the lead is not re-queried every run.
//   match     one person clears the bar; the enrichment call is worth a credit.
//
// EVERY outcome now also carries an `attempt` -- what to record in
// `contact_attempts` (migration 015), which is what stops a lead nobody can
// find from taking a slot in every batch for ever. Two values:
//
//   exhausted  every source has answered and there is no contact. Permanent.
//              That is "Apollo answered, nobody there", and also a refusal this
//              account can never get past: the Free plan's 403 API_INACCESSIBLE
//              is a property of the plan, not a five-minute outage, and it will
//              answer identically on every call until somebody upgrades.
//   refused    anything else -- a 429, a 5xx, a timeout, a response that is not
//              the shape we expect. Retried, but counted, so even a refusal
//              nobody recognised stops after the stage's max_attempts instead
//              of starving the queue.
//
// THE BUG THIS FIXES, measured 2026-10-07: nine leads with no scraped address,
// no address published on their own site and no founder LinkedIn were going to
// Apollo, being refused, and coming straight back to the top of the next hour's
// batch of 10 -- `ORDER BY fit_score DESC` put the same stuck leads first every
// time. At ten such leads no new lead would ever have been looked up again.

const src = $('Resolve Contact').item.json;
const resp = $input.item.json;

// Ordered best-first. Matched as substrings against a lowercased title, so
// "Founder & CEO" and "Co-Founder" both land in tier 0.
const TITLE_TIERS = [
  ['founder', 'co-founder', 'cofounder', 'owner', 'proprietor'],
  ['managing director', 'general manager', 'director general', 'managing partner'],
  ['ceo', 'chief executive'],
  ['business development', 'bd director', 'bd manager', 'commercial director'],
];

// Not a tier -- a tiebreak within one. Keeps a "Business Development Director"
// ahead of a "Business Development Representative" without inventing a fifth
// preference level the spec does not have.
const SENIORITY = ['chief', 'president', 'partner', 'head of', 'vp', 'vice president', 'director', 'manager'];

function tierOf(title) {
  const t = (title || '').toLowerCase();
  if (!t) return -1;
  for (let i = 0; i < TITLE_TIERS.length; i++) {
    for (const kw of TITLE_TIERS[i]) {
      if (t.indexOf(kw) >= 0) return i;
    }
  }
  return -1;
}

function seniorityOf(title) {
  const t = (title || '').toLowerCase();
  for (let i = 0; i < SENIORITY.length; i++) {
    if (t.indexOf(SENIORITY[i]) >= 0) return i;
  }
  return SENIORITY.length;
}

function normDomain(d) {
  if (typeof d !== 'string') return '';
  return d.trim().toLowerCase().replace(/^https?:\/\//, '').replace(/^www\./, '')
    .replace(/[/].*$/, '').replace(/[./]+$/, '');
}

const base = {
  lead_id: src.lead_id,
  domain: src.domain,
  company_name: src.company_name,
  country: src.country,
  fit_score: src.fit_score,
  source: 'apollo',
};

// ---------------------------------------------------------------------------
// Did Apollo actually answer?
// ---------------------------------------------------------------------------
//
// The HTTP node continues on error, so a refusal arrives as a normal item
// carrying an `error` key. API_INACCESSIBLE (the endpoint is not on the account's
// plan) and a 429 are both this shape. Neither is evidence about the company.
// Apollo's Free plan refuses these endpoints outright: 403 with
// API_INACCESSIBLE and "not included in your Free plan" (measured 2026-09-06 on
// both the API-key and the OAuth path, on an account showing 125 unused
// credits -- Section 9's table). That is a permanent property of the plan, so
// the lead has genuinely run out of sources and is retired rather than retried
// every hour for ever. Positive recognition only: anything this does not
// clearly identify as the plan gate stays a retry, because "a refusal is not
// evidence" is still the rule for every refusal that could pass next time.
function isPlanGate(text) {
  const t = String(text || '').toLowerCase();
  if (/\b(429|too many requests|rate limit|timeout|etimedout|econn|socket|enotfound|eai_again|5\d\d)\b/.test(t)) {
    return false;
  }
  return t.indexOf('api_inaccessible') !== -1 ||
    t.indexOf('not included in your') !== -1 ||
    (t.indexOf('403') !== -1 && t.indexOf('forbidden') !== -1) ||
    (t.indexOf('403') !== -1 && t.indexOf('plan') !== -1);
}

// What the free sources did, carried from Resolve Contact so the attempt record
// and the manual-contact queue can say what was actually tried.
function triedWhat() {
  const f = src.free_sources || {};
  const bits = ['no e-mail on the ichgcp profile page'];
  if (f.site_lookup === 'found') bits.push('an address was published on the site');
  else if (f.site_lookup === 'unreachable') bits.push('their website did not load');
  else if (f.site_lookup === 'no-address-found') {
    bits.push('no address published on ' + (Number(f.site_pages_fetched) || 0) + ' pages of their own site' +
      ((f.site_rejected || []).length
        ? ' (found only ' + (f.site_rejected || []).join(', ') + ', which is never a contact mailbox)'
        : ''));
  } else bits.push('site not read (' + (f.site_lookup || 'skipped') + ')');
  bits.push('founder LinkedIn: ' + (f.founder_linkedin || 'none found'));
  return bits.join('; ');
}

if (!resp || typeof resp !== 'object' || resp.error || resp.error_code || !Array.isArray(resp.people)) {
  // JSON.stringify, not String(): n8n wraps an HTTP failure as an object, and
  // String() renders that '[object Object]' -- which turns the one field an
  // operator needs (why did Apollo refuse?) into nothing at all. Same shape
  // code_score.js uses for the ClinicalTrials.gov failure path.
  const err = resp && (resp.error || resp.message);
  const detail = err
    ? (typeof err === 'string' ? err : JSON.stringify(err)).slice(0, 300)
    : 'no people[] array in the response';
  const permanent = isPlanGate(detail) || isPlanGate(JSON.stringify(resp || null));
  return {
    json: Object.assign({}, base, {
      write: false,
      matched: false,
      // A plan gate will answer the same way next hour, so there is nothing to
      // come back for. Anything else is retried.
      retry: !permanent,
      skip_reason: 'Apollo people-search did not answer: ' + detail,
      attempt_row: {
        lead_id: src.lead_id,
        outcome: permanent ? 'exhausted' : 'refused',
        detail: permanent
          ? 'Apollo cannot be called on this account\'s plan (' + detail + '). ' + triedWhat() +
            '. Find a contact by hand, add a `contacts` row and set the lead to contact_found; ' +
            'delete its contact_attempts row to put it back in the queue.'
          : 'Apollo did not answer: ' + detail + '. Retried next run. ' + triedWhat(),
      },
    }),
  };
}

// ---------------------------------------------------------------------------
// Rank what came back
// ---------------------------------------------------------------------------

const leadDomain = normDomain(src.domain);
const knownFounder = (src.known_founder_name || '').trim().toLowerCase();

const ranked = resp.people
  .map(function (p) {
    const org = p.organization || {};
    const orgDomain = normDomain(org.primary_domain || org.website_url || p.organization_domain);
    return {
      person: p,
      tier: tierOf(p.title),
      seniority: seniorityOf(p.title),
      // Apollo can attach a person to an organisation whose domain is not the
      // one searched (former employer, parent company, a same-name business in
      // another country). Spending a credit on that person buys the wrong
      // company's contact, so it is a hard gate, not a ranking penalty.
      domain_ok: !orgDomain || orgDomain === leadDomain,
      // The site named this person as founder. Independent corroboration from a
      // second source outranks a title string alone.
      corroborated:
        !!knownFounder &&
        typeof p.name === 'string' &&
        p.name.trim().toLowerCase() === knownFounder,
    };
  })
  .filter(function (c) { return c.tier >= 0 && c.domain_ok; })
  .sort(function (a, b) {
    if (a.corroborated !== b.corroborated) return a.corroborated ? -1 : 1;
    if (a.tier !== b.tier) return a.tier - b.tier;
    return a.seniority - b.seniority;
  });

if (!ranked.length) {
  const seen = resp.people.length;
  const reason =
    seen === 0
      ? 'Apollo has no people indexed at this domain'
      : 'Apollo returned ' + seen + ' ' + (seen === 1 ? 'person' : 'people') +
        ' at this domain, none in a founder / managing director / CEO / business ' +
        'development role at the searched domain';
  return {
    json: Object.assign({}, base, {
      write: true,
      matched: false,
      retry: false,
      no_match_reason: reason,
      // A tombstone: the lead gets a contacts row carrying no contact. It is
      // written for one reason -- without it the batch query has no way to tell
      // "not looked up yet" from "looked up, nothing there", and every cron run
      // would re-spend a search on the same dead domains forever.
      //
      // It deliberately does NOT advance the lead. Section 8's status flow has
      // no state for "asked and found nothing", and `contact_found` would put a
      // contactless lead in front of Workflow 4, which is exactly what the
      // grounding guard exists to prevent. The lead stays 'scored'.
      payload: {
        lead_id: src.lead_id,
        name: null,
        title: null,
        email: null,
        linkedin_url: null,
        apollo_id: null,
        // Nothing was found, so there is nothing to have verified.
        verified: false,
        advance: false,
        note: reason,
        // Apollo answered: every source has now been asked and none of them
        // reached anybody. Permanent, so the lead leaves the queue and turns up
        // in needs_manual_contact with this detail as its `why`. Inside the
        // payload because Write Contact & Advance records it in the same
        // statement as the tombstone -- one crash point, not two.
        attempt: {
          outcome: 'exhausted',
          detail: reason + '. ' + triedWhat() +
            '. Find a contact by hand, add a `contacts` row and set the lead to contact_found.',
        },
      },
    }),
  };
}

const best = ranked[0];
const p = best.person;

return {
  json: Object.assign({}, base, {
    write: true,
    matched: true,
    retry: false,
    apollo_id: p.id || null,
    candidate: {
      name: p.name || [p.first_name, p.last_name].filter(Boolean).join(' ') || null,
      first_name: p.first_name || null,
      last_name: p.last_name || null,
      title: p.title || null,
      linkedin_url: p.linkedin_url || null,
    },
    match_tier: best.tier,
    corroborated: best.corroborated,
    // Nothing to record here: the payload builders downstream set
    // payload.attempt = null, which makes Write Contact & Advance DELETE any
    // earlier record -- the lead has a channel now, and a stale row would show
    // it in needs_manual_contact as still waiting for a human.
    candidates_considered: resp.people.length,
    candidates_in_role: ranked.length,
  }),
};

// Build Contact Payload (Apollo) — n8n Code node (Run Once for Each Item).
//
// Folds the People Enrichment response into the candidate Pick Best Contact
// already chose. The search that produced the candidate returns no addresses at
// all, by design on Apollo's side; this is the call that costs the credit, so it
// runs exactly once per lead and only for a candidate that already cleared the
// title and domain gates.

const pick = $('Pick Best Contact').item.json;
const resp = $input.item.json;
const cand = pick.candidate || {};

// Same rule as Pick Best Contact and as Workflow 3's ClinicalTrials.gov step: a
// call that did not answer is not evidence. The lead is dropped with no row
// written and stays 'scored' for the next run, rather than being tombstoned as
// though Apollo had looked and found nothing.
if (!resp || typeof resp !== 'object' || resp.error || resp.error_code || !resp.person) {
  // JSON.stringify, not String(): n8n wraps an HTTP failure as an object, and
  // String() renders that '[object Object]' -- which turns the one field an
  // operator needs (why did Apollo refuse?) into nothing at all. Same shape
  // code_score.js uses for the ClinicalTrials.gov failure path.
  const err = resp && (resp.error || resp.message);
  const detail = err
    ? (typeof err === 'string' ? err : JSON.stringify(err)).slice(0, 300)
    : 'no person object in the response';
  return {
    json: {
      write: false,
      lead_id: pick.lead_id,
      domain: pick.domain,
      source: 'apollo',
      credits_spent: 0,
      skip_reason: 'Apollo people-match did not answer: ' + detail,
    },
  };
}

const p = resp.person;

// Apollo returns this literal placeholder when the account cannot see the
// address. Writing it would put an undeliverable string in contacts.email that
// looks exactly like a real one three workflows downstream.
function usableEmail(e) {
  if (typeof e !== 'string') return null;
  const s = e.trim();
  if (!s || s.indexOf('@') < 1) return null;
  if (/^email_not_unlocked@/i.test(s)) return null;
  if (/^(unavailable|not_unlocked|locked)$/i.test(s)) return null;
  return s;
}

const email = usableEmail(p.email);
const status = typeof p.email_status === 'string' ? p.email_status.toLowerCase() : null;

// The one flag Workflow 6 will gate a send on, so it means one thing: the
// address is confirmed, not inferred. Apollo's own 'guessed' status is a
// pattern-derived address -- real enough to keep, not enough to call verified.
const verified = !!email && status === 'verified';

const name = p.name || [p.first_name, p.last_name].filter(Boolean).join(' ') || cand.name || null;
const title = p.title || cand.title || null;
const linkedin = p.linkedin_url || cand.linkedin_url || null;

return {
  json: {
    write: true,
    lead_id: pick.lead_id,
    domain: pick.domain,
    source: 'apollo',
    credits_spent: 1,
    email_status: status,
    payload: {
      lead_id: pick.lead_id,
      name: name,
      title: title,
      email: email,
      linkedin_url: linkedin,
      apollo_id: p.id || pick.apollo_id || null,
      verified: verified,
      // A person with a LinkedIn URL and no email is still contactable -- Section
      // 6 sends LinkedIn by hand, and Workflow 4 drafts that variant separately.
      advance: !!(email || linkedin),
      note:
        'Apollo people-match on a ' +
        (pick.corroborated ? 'site-corroborated ' : '') +
        'tier-' + pick.match_tier + ' title; email_status=' + (status || 'none') +
        '; ' + pick.candidates_in_role + ' of ' + pick.candidates_considered +
        ' indexed people were in an ICP role at this domain',
      // No attempt to record: Apollo answered and found somebody. null makes
      // Write Contact & Advance delete any earlier record, so a lead that was
      // in needs_manual_contact and has since been reached leaves that queue.
      attempt: null,
    },
  },
};

// Build Contact Payload (Scraped) — n8n Code node (Run Once for Each Item).
//
// The zero-credit branch. Everything written here came from a source already on
// disk: the address from the company's own ichgcp profile page, the person from
// the Workflow 2 site extraction. No API was called and no field is inferred.
// Resolve Contact sends two kinds of lead here: one with a scraped address, and
// one with no address but the founder's LinkedIn profile (email null, written
// LinkedIn-only). `source` says which.

const r = $input.item.json;
const c = r.contact || {};

// Section 8 gives `contacts` no column for provenance, and this branch needs the
// distinction to survive: a NULL apollo_id is what marks a row as scrape-sourced.
// It is not a placeholder for a lookup that failed -- those rows are written by
// Pick Best Contact and carry a NULL email too.
const hasChannel = !!(c.email || c.linkedin_url);

return {
  json: {
    write: true,
    lead_id: r.lead_id,
    domain: r.domain,
    source: r.source || 'ichgcp_scrape',
    credits_spent: 0,
    payload: {
      lead_id: r.lead_id,
      name: c.name || null,
      title: c.title || null,
      email: c.email || null,
      linkedin_url: c.linkedin_url || null,
      apollo_id: null,
      // First-party published address: the company stated it about itself.
      verified: c.verified === true,
      // At least one reachable channel, so Workflow 4 has something to draft to.
      advance: hasChannel,
      note: r.evidence || null,
      // No attempt to record: this lead was reached for free. null makes Write
      // Contact & Advance delete any earlier record, so a lead that was once in
      // needs_manual_contact and has since been reached leaves that queue.
      attempt: null,
    },
  },
};
